      $v = [math]::Max(0.0, [math]::Min(1.0, $Value))
      if ($v -lt $b.Target - 0.001) { $b.Shown = $v }   # never slide backwards (a new step starts at 0)
      $b.Target = $v; $b.Sheen = $Sheen
      if ($b.Busy -ne $Busy) { $b.Busy = $Busy; $b.Phase = 0.0 }
